function creerFilePriorite() {
  const heap = [];
  let ordre = 0;

  function estPlusPrioritaire(a, b) {
    return a.priorite < b.priorite ||
      (a.priorite === b.priorite && a.ordre < b.ordre);
  }

  function enqueue(val, priorite) {
    const element = { val, priorite, ordre: ordre++ };
    let index = heap.length;

    heap.push(element);

    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);

      if (!estPlusPrioritaire(heap[index], heap[parent])) {
        break;
      }

      [heap[index], heap[parent]] = [heap[parent], heap[index]];
      index = parent;
    }
  }

  function dequeue() {
    if (heap.length === 0) {
      return undefined;
    }

    const element = heap[0];
    const dernier = heap.pop();

    if (heap.length > 0) {
      heap[0] = dernier;
      let index = 0;

      while (true) {
        const gauche = 2 * index + 1;
        const droite = 2 * index + 2;
        let plusPetit = index;

        if (
          gauche < heap.length &&
          estPlusPrioritaire(heap[gauche], heap[plusPetit])
