function creerEventEmitter() {
  const abonnes = new Map();

  const emitter = {
    on(event, fn) {
      if (typeof fn !== "function") {
        throw new TypeError("Le listener doit être une fonction");
      }

      if (!abonnes.has(event)) {
        abonnes.set(event, []);
      }

      abonnes.get(event).push(fn);
      return emitter;
    },

    off(event, fn) {
      const listeners = abonnes.get(event);

      if (!listeners) {
        return emitter;
      }

      const index = listeners.indexOf(fn);

      if (index !== -1) {
        listeners.splice(index, 1);
      }

      if (listeners.length === 0) {
        abonnes.delete(event);
      }

      return emitter;
    },

    emit(event, ...args) {
      const listeners = abonnes.get(event);

      if (!listeners || listeners.length === 0) {
        return false;
      }

      for (const listener of [...listeners]) {
        listener(...args);
      }

      return true;
    }
  };

  return emitter;
}
