function remplirMatrice(grille, x, y, nouvelleValeur) {
  if (!Array.isArray(grille) || !Array.isArray(grille[y])) {
    return grille;
  }

  if (
    !Number.isInteger(x) ||
    !Number.isInteger(y) ||
    x < 0 ||
    y < 0 ||
    x >= grille[y].length
  ) {
    return grille;
  }

  const valeurInitiale = grille[y][x];

  if (valeurInitiale === nouvelleValeur) {
    return grille;
  }

  const pile = [[x, y]];

  while (pile.length > 0) {
    const [colonne, ligne] = pile.pop();
    const ligneCourante = grille[ligne];

    if (!Array.isArray(ligneCourante)) {
      continue;
    }

    if (
      colonne < 0 ||
      ligne < 0 ||
      colonne >= ligneCourante.length ||
      ligneCourante[colonne] !== valeurInitiale
    ) {
      continue;
    }

    ligneCourante[colonne] = nouvelleValeur;

    pile.push(
      [colonne + 1, ligne],
      [colonne - 1, ligne],
      [colonne, ligne + 1],
      [colonne, ligne - 1]
    );
  }

  return grille;
}
