function fibonacci(n) {
  if (!Number.isInteger(n) || n < 0) {
    throw new RangeError("n doit être un entier positif ou nul.");
  }

  if (n === 0) {
    return 0;
  }

  let precedent = 0;
  let courant = 1;

  for (let index = 2; index <= n; index++) {
    const suivant = precedent + courant;
    precedent = courant;
    courant = suivant;
  }

  return courant;
}

