  if (typeof s !== "string") {
    throw new TypeError("Le paramètre doit être une chaîne.");
  }

  const mots = s.match(/\S+/g) || [];
  return new Set(mots).size;
}

function aplatirTableau(tab) {
  if (!Array.isArray(tab)) {
    throw new TypeError("Le paramètre doit être un tableau.");
  }

  return tab.flat(1);
}

function rotationDroite(tab, k) {
  if (!Array.isArray(tab)) {
    throw new TypeError("Le paramètre tab doit être un tableau.");
  }

  if (!Number.isInteger(k)) {
    throw new TypeError("Le paramètre k doit être un entier.");
  }

  if (tab.length === 0) {
    return [];
  }

  const decalage = ((k % tab.length) + tab.length) % tab.length;

  if (decalage === 0) {
    return tab.slice();
  }

  const pointDeDecoupe = tab.length - decalage;

  return tab.slice(pointDeDecoupe).concat(tab.slice(0, pointDeDecoupe));
}

