class LRUCache {
 constructor(capacite) {
  this.capacite = Number.isFinite(capacite) ? Math.max(0, Math.floor(capacite)) : 0;
  this._cache = new Map();
 }
 get(cle) {
  if (!this._cache.has(cle)) return -1;
  const valeur=this._cache.get(cle);
  this._cache.delete(cle);
  this._cache.set(cle,valeur);
  return valeur;
 }
 put(cle,valeur) {
  if (this.capacite === 0) return valeur;
  if (this._cache.has(cle)) this._cache.delete(cle);
  this._cache.set(cle,valeur);
  if (this._cache.size > this.capacite) {
    const plusAncien=this._cache.keys().next().value;
    this._cache.delete(plusAncien);
  }
  return valeur;
 }
}
