   if (Array.isArray(valeur)) {
      const copie=[];
      memo.set(valeur,copie);
      copierProprietes(valeur,copie);
      return copie;
   }

   const copie=Object.create(Object.getPrototypeOf(valeur));
   memo.set(valeur,copie);
   copierProprietes(valeur,copie);
   return copie;
 }

 function copierProprietes(source,target) {
   for (const cle of Reflect.ownKeys(source)) {
      const descripteur=Object.getOwnPropertyDescriptor(source,cle);
      if (Object.prototype.hasOwnProperty.call(descripteur,"value")) {
         descripteur.value=copieProfonde(descripteur.value);
      }
      Object.defineProperty(target,cle,descripteur);
   }
 }
 return copieProfonde(obj);
}

