trier_tableau in-place heap sort:
```
function trier_tableau(arr) {
  if (!Array.isArray(arr) || arr.length < 2) return arr;

  const n = arr.length;
  function swap(i, j) {
    const tmp = arr[i];
    arr[i] = arr[j];
    arr[j] = tmp;
  }
  function siftDown(root, end) {
    while (true) {
      const left = 2 * root + 1;
      if (left > end) break;
      let child = left;
      const right = left + 1;
      if (right <= end && arr[right] > arr[left]) child = right;
      if (arr[root] >= arr[child]) break;
      swap(root, child);
      root = child;
    }
  }
  for (let root = Math.floor(n / 2) - 1; root >= 0; root--) {
    siftDown(root, n - 1);
  }
  for (let end = n - 1; end > 0; end--) {
    swap(0, end);
    siftDown(0, end - 1);
  }
  return arr;
}
```
